    required this.freeAiEnabled,
    required this.localAiEnabled,
    required this.paidCodeAiEnabled,
    required this.callAgentEnabled,
    this.emailAgentEnabled = false,
    this.customerWhatsAppAgentEnabled = false,
    this.ownerWhatsAppAgentEnabled = false,
    this.emergencyWhatsAppAgentEnabled = false,
    this.voiceSuperAdminAgentEnabled = false,
    required this.approvalEngineEnabled,
    required this.auditLoggingEnabled,
    this.paidReasoningEnabled = false,
    this.askBeforePaid = true,
    this.paidReasoningPerTaskLimitRs = 0,
    this.paidReasoningDailyLimitRs = 0,
    this.paidReasoningMonthlyLimitRs = 0,
    required this.monthlyPaidCodeBudgetRs,
    required this.paidCodeBudgetUsedRs,
    required this.emergencyActivatedAt,
    required this.emergencyActivatedBy,
    required this.emergencyReason,
    required this.createdAt,
    required this.updatedAt,
  });

  factory AgentMasterSettings.safeDefaults() {
    final DateTime now = DateTime.now();

    return AgentMasterSettings(
      masterEnabled: false,
      emergencyReadOnly: true,
      freeAiEnabled: false,
      localAiEnabled: false,
      paidCodeAiEnabled: false,
      callAgentEnabled: false,
      emailAgentEnabled: false,
      customerWhatsAppAgentEnabled: false,
      ownerWhatsAppAgentEnabled: false,
      emergencyWhatsAppAgentEnabled: false,
      voiceSuperAdminAgentEnabled: false,
      approvalEngineEnabled: true,
      auditLoggingEnabled: true,
      paidReasoningEnabled: false,
      askBeforePaid: true,
      paidReasoningPerTaskLimitRs: 0,
      paidReasoningDailyLimitRs: 0,
      paidReasoningMonthlyLimitRs: 0,
      monthlyPaidCodeBudgetRs: 0,
      paidCodeBudgetUsedRs: 0,
      emergencyActivatedAt: now,
      emergencyActivatedBy: 'system',
      emergencyReason: 'Safe defaults until owner explicitly enables AI.',
      createdAt: now,
      updatedAt: null,
    );
  }

  bool get paidBudgetAvailable =>
      monthlyPaidCodeBudgetRs > 0 &&
      paidCodeBudgetUsedRs < monthlyPaidCodeBudgetRs;

  bool get anyWriteAllowed => masterEnabled && !emergencyReadOnly;

  bool get freeAiOperational => masterEnabled && freeAiEnabled;

  bool get paidCodeAiOperational =>
      masterEnabled && paidCodeAiEnabled && paidBudgetAvailable;

  bool get paidReasoningBudgetConfigured =>
      paidReasoningPerTaskLimitRs > 0 &&
      paidReasoningDailyLimitRs > 0 &&
      paidReasoningMonthlyLimitRs > 0;

  bool get paidReasoningOperational =>
      masterEnabled &&
      !emergencyReadOnly &&
      paidReasoningEnabled &&
      paidReasoningBudgetConfigured;
  AgentMasterSettings copyWith({
    bool? masterEnabled,
    bool? emergencyReadOnly,
    bool? freeAiEnabled,
    bool? localAiEnabled,
    bool? paidCodeAiEnabled,
    bool? callAgentEnabled,
    bool? emailAgentEnabled,
    bool? customerWhatsAppAgentEnabled,
    bool? ownerWhatsAppAgentEnabled,
    bool? emergencyWhatsAppAgentEnabled,
    bool? voiceSuperAdminAgentEnabled,
    bool? approvalEngineEnabled,
    bool? auditLoggingEnabled,
    bool? paidReasoningEnabled,
    bool? askBeforePaid,
    int? paidReasoningPerTaskLimitRs,
    int? paidReasoningDailyLimitRs,
    int? paidReasoningMonthlyLimitRs,
    int? monthlyPaidCodeBudgetRs,
    int? paidCodeBudgetUsedRs,
    DateTime? emergencyActivatedAt,
    bool clearEmergencyActivatedAt = false,
    String? emergencyActivatedBy,
    String? emergencyReason,
    DateTime? createdAt,
    DateTime? updatedAt,
  }) {
    return AgentMasterSettings(
      masterEnabled: masterEnabled ?? this.masterEnabled,
      emergencyReadOnly: emergencyReadOnly ?? this.emergencyReadOnly,
      freeAiEnabled: freeAiEnabled ?? this.freeAiEnabled,
      localAiEnabled: localAiEnabled ?? this.localAiEnabled,
      paidCodeAiEnabled: paidCodeAiEnabled ?? this.paidCodeAiEnabled,
      callAgentEnabled: callAgentEnabled ?? this.callAgentEnabled,
      emailAgentEnabled: emailAgentEnabled ?? this.emailAgentEnabled,
      customerWhatsAppAgentEnabled:
          customerWhatsAppAgentEnabled ?? this.customerWhatsAppAgentEnabled,
      ownerWhatsAppAgentEnabled:
          ownerWhatsAppAgentEnabled ?? this.ownerWhatsAppAgentEnabled,
      emergencyWhatsAppAgentEnabled:
          emergencyWhatsAppAgentEnabled ?? this.emergencyWhatsAppAgentEnabled,
      voiceSuperAdminAgentEnabled:
          voiceSuperAdminAgentEnabled ?? this.voiceSuperAdminAgentEnabled,
      approvalEngineEnabled:
          approvalEngineEnabled ?? this.approvalEngineEnabled,
      auditLoggingEnabled: auditLoggingEnabled ?? this.auditLoggingEnabled,
      paidReasoningEnabled: paidReasoningEnabled ?? this.paidReasoningEnabled,
      askBeforePaid: askBeforePaid ?? this.askBeforePaid,
      paidReasoningPerTaskLimitRs:
          paidReasoningPerTaskLimitRs ?? this.paidReasoningPerTaskLimitRs,
      paidReasoningDailyLimitRs:
          paidReasoningDailyLimitRs ?? this.paidReasoningDailyLimitRs,
      paidReasoningMonthlyLimitRs:
          paidReasoningMonthlyLimitRs ?? this.paidReasoningMonthlyLimitRs,
      monthlyPaidCodeBudgetRs:
          monthlyPaidCodeBudgetRs ?? this.monthlyPaidCodeBudgetRs,
      paidCodeBudgetUsedRs: paidCodeBudgetUsedRs ?? this.paidCodeBudgetUsedRs,
      emergencyActivatedAt: clearEmergencyActivatedAt
          ? null
          : (emergencyActivatedAt ?? this.emergencyActivatedAt),
      emergencyActivatedBy: emergencyActivatedBy ?? this.emergencyActivatedBy,
      emergencyReason: emergencyReason ?? this.emergencyReason,
      createdAt: createdAt ?? this.createdAt,
      updatedAt: updatedAt ?? this.updatedAt,
    );
  }

  void validate() {
    if (paidReasoningPerTaskLimitRs < 0 ||
        paidReasoningDailyLimitRs < 0 ||
        paidReasoningMonthlyLimitRs < 0) {
      throw const AgentSettingsValidationException(
        'Paid Reasoning Rs limits cannot be negative.',
      );
    }

    if (paidReasoningEnabled && !paidReasoningBudgetConfigured) {
      throw const AgentSettingsValidationException(
        'Paid Reasoning cannot be enabled until per-task, daily and monthly Rs limits are all positive.',
      );
    }
    if (monthlyPaidCodeBudgetRs < 0) {
      throw const AgentSettingsValidationException(
        'monthlyPaidCodeBudgetRs cannot be negative.',
      );
    }

    if (paidCodeBudgetUsedRs < 0) {
      throw const AgentSettingsValidationException(
        'paidCodeBudgetUsedRs cannot be negative.',
      );
    }

    if (paidCodeAiEnabled && monthlyPaidCodeBudgetRs <= 0) {
      throw const AgentSettingsValidationException(
        'Paid Code AI cannot be enabled without a positive monthly budget.',
      );
    }
  }

  Map<String, dynamic> toMap() {
    return <String, dynamic>{
      'masterEnabled': masterEnabled,
      'emergencyReadOnly': emergencyReadOnly,
      'freeAiEnabled': freeAiEnabled,
      'localAiEnabled': localAiEnabled,
      'paidCodeAiEnabled': paidCodeAiEnabled,
      'callAgentEnabled': callAgentEnabled,
      'emailAgentEnabled': emailAgentEnabled,
      'customerWhatsAppAgentEnabled': customerWhatsAppAgentEnabled,
      'ownerWhatsAppAgentEnabled': ownerWhatsAppAgentEnabled,
      'emergencyWhatsAppAgentEnabled': emergencyWhatsAppAgentEnabled,
      'voiceSuperAdminAgentEnabled': voiceSuperAdminAgentEnabled,
      'approvalEngineEnabled': approvalEngineEnabled,
      'auditLoggingEnabled': auditLoggingEnabled,
      'paidReasoningEnabled': paidReasoningEnabled,
      'askBeforePaid': askBeforePaid,
      'paidReasoningPerTaskLimitRs': paidReasoningPerTaskLimitRs,
      'paidReasoningDailyLimitRs': paidReasoningDailyLimitRs,
      'paidReasoningMonthlyLimitRs': paidReasoningMonthlyLimitRs,
      'monthlyPaidCodeBudgetRs': monthlyPaidCodeBudgetRs,
      'paidCodeBudgetUsedRs': paidCodeBudgetUsedRs,
      'emergencyActivatedAt': _timestamp(emergencyActivatedAt),
      'emergencyActivatedBy': emergencyActivatedBy,
      'emergencyReason': emergencyReason,
      'createdAt': Timestamp.fromDate(createdAt),
      'updatedAt': _timestamp(updatedAt),
    };
  }

  factory AgentMasterSettings.fromMap(Map<String, dynamic> map) {
    final AgentMasterSettings settings = AgentMasterSettings(
      masterEnabled: _bool(map['masterEnabled']),
      emergencyReadOnly: _bool(map['emergencyReadOnly'], fallback: true),
      freeAiEnabled: _bool(map['freeAiEnabled']),
      localAiEnabled: _bool(map['localAiEnabled']),
      paidCodeAiEnabled: _bool(map['paidCodeAiEnabled']),
      callAgentEnabled: _bool(map['callAgentEnabled']),
      emailAgentEnabled: _bool(map['emailAgentEnabled']),
      customerWhatsAppAgentEnabled: _bool(map['customerWhatsAppAgentEnabled']),
      ownerWhatsAppAgentEnabled: _bool(map['ownerWhatsAppAgentEnabled']),
      emergencyWhatsAppAgentEnabled: _bool(
        map['emergencyWhatsAppAgentEnabled'],
      ),
      voiceSuperAdminAgentEnabled: _bool(map['voiceSuperAdminAgentEnabled']),
      approvalEngineEnabled: _bool(
        map['approvalEngineEnabled'],
        fallback: true,
      ),
      auditLoggingEnabled: _bool(map['auditLoggingEnabled'], fallback: true),
      paidReasoningEnabled: _bool(map['paidReasoningEnabled']),
      askBeforePaid: _bool(map['askBeforePaid'], fallback: true),
      paidReasoningPerTaskLimitRs: _int(map['paidReasoningPerTaskLimitRs']),
      paidReasoningDailyLimitRs: _int(map['paidReasoningDailyLimitRs']),
      paidReasoningMonthlyLimitRs: _int(map['paidReasoningMonthlyLimitRs']),
      monthlyPaidCodeBudgetRs: _int(map['monthlyPaidCodeBudgetRs']),
      paidCodeBudgetUsedRs: _int(map['paidCodeBudgetUsedRs']),
      emergencyActivatedAt: _date(map['emergencyActivatedAt']),
      emergencyActivatedBy: _string(map['emergencyActivatedBy']),
      emergencyReason: _string(map['emergencyReason']),
      createdAt: _date(map['createdAt']) ?? DateTime.now(),
      updatedAt: _date(map['updatedAt']),
    );

    try {
      settings.validate();
      return settings;
    } on AgentSettingsValidationException {
      return AgentMasterSettings.safeDefaults();
    }
  }

  static String _string(dynamic value) {
    if (value == null) return '';
    return value.toString().trim();
  }

  static bool _bool(dynamic value, {bool fallback = false}) {
    if (value == null) return fallback;
    if (value is bool) return value;
    final String normalized = value.toString().toLowerCase().trim();
    if (normalized == 'true') return true;
    if (normalized == 'false') return false;
    return fallback;
  }

  static int _int(dynamic value) {
    if (value is int) return value;
    if (value is num) return value.toInt();
    return int.tryParse(value?.toString() ?? '') ?? 0;
  }

  static DateTime? _date(dynamic value) {
    if (value == null) return null;
    if (value is Timestamp) return value.toDate();
    if (value is DateTime) return value;
    if (value is String) return DateTime.tryParse(value);
    return null;
  }

  static Timestamp? _timestamp(DateTime? value) {
    return value == null ? null : Timestamp.fromDate(value);
  }
}

class AgentSettingsValidationException implements Exception {
  final String message;

  const AgentSettingsValidationException(this.message);

  @override
  String toString() => 'AgentSettingsValidationException: $message';
}
